import os

def test_socket_path():
    path = '/tmp/service-test.sock'
    if os.path.exists(path):
        os.unlink(path)
    open(path, 'w').close()

import subprocess

def lint_gate():
    result = subprocess.run(['ruff', 'check', '.'], capture_output=True)
    return {'verdict': 'clean', 'log': result.stdout.decode()}

def test_creates_report(cli):
    result = cli.run(['report'])
    assert result.exit_code == 0

def test_rejects_bad_token_and_stores_nothing(client, db):
    response = client.post('/tokens', json={'token': 'bad'})
    assert response.status_code == 400

def test_rejects_bad_token(client):
    response = client.post('/tokens', json={'token': 'bad'})
    assert response.status_code == 400
    assert response.json == {'error': 'invalid token'}
